package com.aetherforge.repo;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class OperationalRepository {private final JdbcTemplate db;public OperationalRepository(JdbcTemplate db){this.db=db;}public List<Map<String,Object>> alerts(){return db.queryForList("select a.*,m.code machine_code from alert a left join machine m on m.id=a.machine_id order by a.created_at desc limit 80");}public int updateAlert(String id,String status){return db.update("update alert set status=?,acknowledged_at=case when ?='ACKNOWLEDGED' then now() else acknowledged_at end where id::text=?",status,status,id);}public List<Map<String,Object>> maintenance(){return db.queryForList("select mr.*,m.code machine_code from maintenance_record mr join machine m on m.id=mr.machine_id order by mr.scheduled_at desc nulls last");}public List<Map<String,Object>> production(){return db.queryForList("select p.recorded_at,pl.code line_code,p.target,p.actual,p.throughput,p.cycle_time,p.downtime_minutes,p.oee,p.quality,p.scrap from production_metric p join production_line pl on pl.id=p.line_id where p.recorded_at>now()-interval '7 days' order by p.recorded_at desc limit 300");}public List<Map<String,Object>> energy(){return db.queryForList("select e.recorded_at,m.code machine_code,e.kwh,e.energy_per_unit,e.peak_kw,e.cost,e.baseline,e.anomaly from energy_metric e join machine m on m.id=e.machine_id order by e.recorded_at desc limit 240");}public List<Map<String,Object>> predictions(){return db.queryForList("select fp.*,m.code machine_code from failure_prediction fp join machine m on m.id=fp.machine_id order by fp.failure_probability desc");}public List<Map<String,Object>> recommendations(){return db.queryForList("select ar.*,m.code machine_code from ai_recommendation ar left join machine m on m.id=ar.machine_id order by ar.created_at desc limit 40");}public List<Map<String,Object>> autonomous(){return db.queryForList("select aa.*,m.code machine_code from autonomous_action aa left join machine m on m.id=aa.machine_id order by aa.created_at desc");}public Map<String,Object> action(String id){return db.queryForMap("select aa.*,m.code machine_code from autonomous_action aa left join machine m on m.id=aa.machine_id where aa.id::text=?",id);}public void setAction(String id,String state,String actor){db.update("update autonomous_action set state=?,actor=?,updated_at=now() where id::text=?",state,actor,id);}public int createMaintenance(String machineId,String priority,String actor){return db.update("insert into maintenance_record(factory_id,machine_id,status,priority,technician,scheduled_at,notes,ai_recommendation) select factory_id,id,'OPEN',?,?,now()+interval '2 hours','Autonomous maintenance work order','Created from autonomous operations' from machine where id::text=?",priority,actor,machineId);}public void recoverMachine(String machineId){db.update("update machine set status='RUNNING',health=97,failure_probability=.05,rul_hours=2200 where id::text=?",machineId);}public void audit(String actor,String role,String action,String entity,String entityId,String result,String req){db.update("insert into audit_log(actor,role,action,entity,entity_id,result,request_id) values(?,?,?,?,?,?,?)",actor,role,action,entity,entityId,result,req);}public List<Map<String,Object>> audit(){return db.queryForList("select * from audit_log order by created_at desc limit 200");}}
